#!/usr/bin/env python3
"""
make_demo_archive.py - builds a FAKE but realistic-looking VK data archive for the README
screenshots of vk_archive_enrich. Everything in it is invented: people, ids, messages, pictures
(drawn procedurally with Pillow). The run is deterministic (seeded) and needs no network.

    python3 tools/make_demo_archive.py OUT_DIR [--style PATH/TO/style.css] [--seed N] [--jobs N]

creates

    OUT_DIR/archive/            a fake official export: cp1251 pages with the same file names,
                                pagination and markup as the real one
    OUT_DIR/archive_enriched/   _data/*.json + media/... as if vk_archive_enrich had already
                                fetched everything from the VK API

so that

    python3 vk_archive_enrich.py OUT_DIR/archive OUT_DIR/archive_enriched --offline --github-activity

renders the improved pages without touching the network. VK's style.css is not part of this
repository (it is VK's): pass the one from your own export with --style to get the real look,
otherwise a small fallback stylesheet is written. If ffmpeg is on PATH, short video clips are
made from the video covers; without it the videos only have covers.

Needs Python 3.9+ and Pillow.
"""
