def log(*a):
    print(time.strftime('%H:%M:%S'), *a, flush=True)


def lts_of(d, h=0, m=0, s=0):
    """Local (archive) time as a naive epoch."""
    return calendar.timegm((d.year, d.month, d.day, h, m, s))


def ldt(lts):
    return datetime.fromtimestamp(lts, timezone.utc)


def hdr_date(lts):
    """'21 мая 2017 в 21:55:18' - message headers."""
    t = ldt(lts)
    return '%d %s %d в %d:%02d:%02d' % (t.day, RU_MON[t.month - 1], t.year, t.hour, t.minute, t.second)


def list_date(lts):
    """'21 мая 2017 в 21:55' - friends, wall, comments, photos."""
    t = ldt(lts)
    return '%d %s %d в %d:%02d' % (t.day, RU_MON[t.month - 1], t.year, t.hour, t.minute)


def utc(lts):
    """API dates are real UTC epochs."""
    return lts - TZ


def year_frac(d):
    return d.year + (d.timetuple().tm_yday - 1) / 366.0


_ENC = {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;', '!': '&#33;', '\\': '&#092;', '\n': '<br>'}


def enc(s):
    """Text the way the export writes it: escaped, '!' as &#33;, characters cp1251 lacks as &#N;."""
    out = []
    for ch in s or '':
        r = _ENC.get(ch)
        if r is None:
            try:
                ch.encode('cp1251')
                r = ch
            except UnicodeEncodeError:
                r = '&#%d;' % ord(ch)
        out.append(r)
    return ''.join(out)


def plural(n, forms):
    n = abs(n) % 100
    if 10 < n < 20:
        return forms[2]
    n %= 10
    return forms[0] if n == 1 else forms[1] if 2 <= n <= 4 else forms[2]


def stable_seed(*parts):
    return int.from_bytes(hashlib.sha256('|'.join(map(str, parts)).encode()).digest()[:8], 'big')


def interp(knots, x):
    """Piecewise-linear function given by [(x, y), ...]."""
    if x <= knots[0][0]:
        return knots[0][1]
    for (x0, y0), (x1, y1) in zip(knots, knots[1:]):
        if x <= x1:
            return y0 + (y1 - y0) * (x - x0) / (x1 - x0)
    return knots[-1][1]


def strip_private(o):
    """Drop the '_...' helper keys before writing API objects to json."""
    if isinstance(o, dict):
        return {k: strip_private(v) for k, v in o.items() if not k.startswith('_')}
    if isinstance(o, list):
        return [strip_private(x) for x in o]
    return o


def write_bytes(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'wb') as f:
        f.write(data)


def write_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(strip_private(obj), f, ensure_ascii=False)


