GROUP_PHOTOS = {'kodim': ['board', 'coffee', 'city'], 'koty': ['cat'], 'doroga': ['mountains', 'lake', 'forest', 'landscape'],
                'recepty': ['food', 'cake', 'coffee'], 'kosmos': ['space', 'landscape'], 'diafragma': ['city', 'sunset', 'landscape'],
                'podslushano': ['city', 'board'], 'pyatka': ['meadow', 'landscape'], 'nastolki': ['party', 'coffee'],
                'afisha': ['city', 'party', 'food'], 'polka': ['books'], 'kolesa': ['food']}
# how often a scene with an attachment is picked compared to plain chatter
MEDIA_W = {'photo': 0.3, 'album': 0.22, 'link': 0.2, 'poll': 0.1, 'audio': 0.07, 'doc': 0.3, 'voice': 0.55, 'video': 0.25,
           'wall': 0.4, 'fwd': 0.45, 'call': 0.6}
OWNER_P = {'uni': 0.22, 'work': 0.35, 'hike': 0.35, 'family': 0.15, 'football': 0.3, 'flat': 0.5}
LINK_OWNER = -200000099  # link previews are photos of some service community

_CHOICE = re.compile(r'\[([^\[\]]*)\]')
_SPK = re.compile(r'\(\(([^()|]*)\|([^()|]*)\)\)')
_ADR = re.compile(r'\{\{([^{}|]*)\|([^{}|]*)\}\}')
_SLOT = re.compile(r'\{(\w+)\}')
_TOKEN = re.compile(r'<<([^<>]*)>>')


def expand(rng, s, spk_f=False, adr_f=False, dyn=None):
    def slot(m):
        k = m.group(1)
        if dyn and k in dyn:
            return dyn[k]()
        return rng.choice(SLOTS[k]) if k in SLOTS else m.group(0)
    s = _SLOT.sub(slot, s)
    s = _SPK.sub(lambda m: m.group(2) if spk_f else m.group(1), s)
    s = _ADR.sub(lambda m: m.group(2) if adr_f else m.group(1), s)
    return _CHOICE.sub(lambda m: rng.choice(m.group(1).split('|')), s)


def parse_scenes(text):
    out = []
    for block in re.split(r'\n\s*\n', text.strip()):
        lines = []
        for ln in block.strip().split('\n'):
            role, _, t = ln.partition(':')
            lines.append((role.strip(), t.strip()))
        out.append(lines)
    return out


def poisson(rng, lam):
    if lam <= 0:
        return 0
    if lam > 30:
        return max(0, int(round(rng.gauss(lam, math.sqrt(lam)))))
    L, k, p = math.exp(-lam), 0, 1.0
    while True:
        p *= rng.random()
        if p <= L:
            return k
        k += 1


def rand_hex(rng, n):
    return '%0*x' % (n, rng.getrandbits(4 * n))


def rand_token(rng, n, alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-'):
    return ''.join(rng.choice(alphabet) for _ in range(n))


# days without connection (hiking far away): the owner writes nothing, friends hardly write either
OFFLINE = [(date(2016, 7, 4), 6), (date(2017, 7, 16), 8), (date(2019, 7, 7), 10), (date(2021, 7, 12), 7),
           (date(2023, 7, 23), 8), (date(2025, 7, 20), 9), (date(2020, 2, 10), 5)]


class Engine:
    """Mixin with the message generator (used by World)."""

    def offline(self, d):
        return any(s <= d < s + timedelta(n) for s, n in OFFLINE)

    def quiet(self, d):
        """About one day in 25 the owner is too busy for VK."""
        return stable_seed(self.seed, 'quiet', d.toordinal()) % 100 < 4

    # -- calendar --
    def in_trip(self, d):
        return any(s <= d < s + timedelta(n) for s, n in TRIPS)

    def day_factor(self, c, d):
        wd, m, md = d.weekday(), d.month, (d.month, d.day)
        k = c.kind
        f = 1.0
        trip = self.in_trip(d)
        if k in ('personal', 'old', 'flat'):
            f *= [1, 1, 1, 1, 1.1, 0.9, 0.95][wd]
            if m == 1 and d.day <= 8:
                f *= 1.3
            if c.peer == self.KATYA and trip and d.year >= 2019:
                f *= 0.3  # travelling together
            elif trip:
                f *= 0.6
        elif k == 'work':
            f *= [1.05, 1, 1, 1, 0.9, 0.03, 0.02][wd]
            if md in HOLIDAYS:
                f *= 0.05
            if trip:
                f *= 0.1
        elif k == 'uni':
            f *= [1.1, 1.1, 1.05, 1.05, 1, 0.45, 0.55][wd]
            f *= {1: 1.6, 6: 1.6, 7: 0.08, 8: 0.12, 9: 1.3, 12: 1.2}.get(m, 1)
            if md in HOLIDAYS:
                f *= 0.4
        elif k == 'football':
            f *= 5.0 if wd == 2 else 1.0 if wd == 1 else 0.25
            f *= 0.35 if m in (12, 1, 2) else 1
        elif k == 'hike':
            f *= [1.2, 0.8, 0.8, 1.3, 1.6, 1.5, 1.4][wd]
            f *= {5: 1.5, 6: 1.9, 7: 2.0, 8: 1.9, 9: 1.4, 10: 0.9}.get(m, 0.35)
            if trip:
                f *= 4.5
        elif k == 'family':
            f *= [1, 1, 1, 1, 1, 1.3, 1.4][wd] * (1.3 if m in (6, 7, 8) else 1)
        elif k == 'bot':
            f *= [0.8, 0.8, 0.9, 1, 1.4, 1.5, 1.2][wd]
        elif k == 'news':
            f *= 6 if wd == 4 else 0.12
        return f

    def hours(self, c, d):
        k = c.kind
        if k in ('personal', 'flat', 'football', 'hike'):
            return H_STUDENT if d < date(2019, 7, 1) else H_PERSONAL
        return {'work': H_WORK, 'uni': H_UNI, 'old': H_OLD, 'family': H_FAMILY, 'bot': H_FOOD, 'news': H_NEWS}[k]

    # -- conversations --
    def gen_all(self):
        self.scene_cache = {k: parse_scenes(v) for k, v in SCENES.items()}
        for c in self.convs:
            self.msgs[c.peer] = self.gen_conv(c)
        self.add_specials()
        self.add_showcases()
        self.add_services()
        self.finalize()

    def gen_conv(self, c):
        rng = random.Random(stable_seed(self.seed, 'conv', c.peer))
        scenes = self.scene_cache[c.scene]
        if c.total < 40:  # a one-off chat: every scene once, a day apart
            out = []
            for i, sc in enumerate(scenes):
                out.extend(self.play(rng, c, sc, lts_of(c.start + timedelta(i), rng.randint(10, 20), rng.randint(0, 59)), out))
            return out
        sw = []
        for sc in scenes:
            k = 1.0
            for _, t in sc:
                for tok in _TOKEN.findall(t):
                    k = min(k, MEDIA_W.get(tok.split(':')[0], 1.0))
            sw.append(k if c.kind not in ('bot', 'news') else 1.0)
        end = min(c.end, date(2026, 10, 10) if c.showcase else LAST_DAY)
        days = [c.start + timedelta(i) for i in range((end - c.start).days + 1)]
        w = []
        for d in days:
            yf = year_frac(d)
            x = interp(c.shape, yf) * self.day_factor(c, d)
            if c.kind not in ('bot', 'news'):
                x *= interp(OWNER_ACTIVITY, yf)
                if self.offline(d):
                    x *= 0.04
                elif self.quiet(d) and c.peer < 2000000000:
                    x *= 0.1
            w.append(x * math.exp(rng.gauss(0, 0.55)))
        for _ in range(max(1, len(days) // 240)):  # busy streaks and silent breaks
            i = rng.randrange(len(days))
            mult, n = (rng.uniform(1.8, 3.2), rng.randint(3, 12)) if rng.random() < 0.6 else (0.05, rng.randint(5, 30))
            for j in range(i, min(len(days), i + n)):
                w[j] *= mult
        avg = sum(len(s) for s in scenes) / len(scenes) + (1.4 * c.filler)
        W = sum(w) or 1
        out = []
        for d, x in zip(days, w):
            n = poisson(rng, c.total * x / W / avg)
            if not n:
                continue
            hp = self.hours(c, d)
            starts = sorted(lts_of(d, rng.choices(range(24), hp)[0], rng.randint(0, 59), rng.randint(0, 59)) for _ in range(n))
            last = 0
            for t0 in starts:
                t0 = max(t0, last + rng.randint(300, 2400))
                ms = self.play(rng, c, rng.choices(scenes, sw)[0], t0, out)
                if ms:
                    last = ms[-1]['lts']
                    out.extend(ms)
        return [m for m in out if m['lts'] < EXPORT_TS - 1800]

    def roles_for(self, rng, c, scene):
        letters = []
        for r, _ in scene:
            if r not in letters:
                letters.append(r)
        roles = {}
        if c.peer < 2000000000:
            other = c.peer
            roles.update(O=SELF_ID, X=other, G=other)
            if rng.random() < 0.5:
                roles.update(A=SELF_ID, B=other)
            else:
                roles.update(A=other, B=SELF_ID)
            return roles
        roles.update(c.roles)
        roles['O'] = SELF_ID
        free = [m for m in c.pool if m not in roles.values()]
        rng.shuffle(free)
        for L in letters:
            if L not in roles:
                roles[L] = free.pop() if free else rng.choice(c.pool)
        if 'O' not in letters and rng.random() < OWNER_P.get(c.kind, 0.2):
            cand = [L for L in letters if L in 'ABCD']
            if cand:
                roles[rng.choice(cand)] = SELF_ID
        return roles

    def play(self, rng, c, scene, t0, history, roles=None):
        roles = roles or self.roles_for(rng, c, scene)
        drafts = [(roles.get(r, SELF_ID), t) for r, t in scene]
        if c.kind in ('bot', 'news'):
            pass
        elif c.filler and rng.random() < c.filler:
            speakers = list({u for u, _ in drafts}) or [SELF_ID]
            for _ in range(rng.choice([1, 1, 2])):
                u = rng.choice(speakers if c.peer < 2000000000 else speakers + [rng.choice(c.pool)])
                if rng.random() < 0.12:
                    t = '<<sticker>>'
                else:
                    t = rng.choice(FILLERS if c.peer < 2000000000 else GROUP_FILLERS)
                drafts.insert(rng.randint(1, len(drafts)), (u, t))
        if c.photo_rate and rng.random() < c.photo_rate * 0.5 and c.kind not in ('bot', 'news'):
            u = rng.choice([u for u, _ in drafts])
            kind = rng.choice(c.photo_kinds)
            cap = rng.choice(CAPTIONS.get(kind, CAPTIONS['any']))
            n = rng.choice([1, 1, 1, 2, 3])
            tok = '<<photo:%s>>' % kind if n == 1 else '<<album:%d:%s>>' % (n, kind)
            drafts.insert(rng.randint(0, len(drafts)), (u, (cap + ' ' + tok).strip()))
        out, t, prev = [], t0, None
        for uid, text in drafts:
            if prev is not None:
                if uid == prev:
                    t += rng.randint(3, 40)
                else:
                    t += int(min(900, rng.lognormvariate(3.8, 0.9))) + 2
                if rng.random() < 0.05:
                    t += rng.randint(600, 5400)
            m = self.make_msg(rng, c, uid, t, text, history, out)
            if m:
                out.append(m)
            prev = uid
        return out

    def make_msg(self, rng, c, uid, t, text, history, current=()):
        other = c.peer if 0 < c.peer < 2000000000 else None
        adr = SELF_ID if uid != SELF_ID else (other or SELF_ID)
        dyn = {'order': lambda: str(rng.randint(10000, 99999))}
        text = expand(rng, text, self.sex(uid) == 'f', self.sex(adr) == 'f', dyn)
        tokens = _TOKEN.findall(text)
        text = _TOKEN.sub(' ', text)
        text = re.sub(r'[ \t]+', ' ', text).strip().replace(' // ', '\n').replace('//', '\n')
        m = {'peer': c.peer, 'from_id': uid, 'lts': t, 'text': text, 'atts': [], 'fwd': [], 'reply': None,
             'service': None, 'edited': None}
        recent = list(history[-40:]) + list(current)
        for tok in tokens:
            self.apply_token(rng, c, m, tok, recent)
        if not (m['text'] or m['atts'] or m['fwd']):
            return None
        if not self.exact and not tokens and m['text'] and c.kind not in ('bot', 'news') and \
                rng.random() < (0.06 if c.peer >= 2000000000 else 0.025):
            self.apply_token(rng, c, m, 'reply', recent)  # "в ответ на ..." like people do in busy chats
        if m['text'] and len(m['text']) > 12 and not m['atts'] and rng.random() < 0.012:
            m['edited'] = t + rng.randint(15, 400)
        return m

    # -- attachments --
    def apply_token(self, rng, c, m, tok, history):
        parts = tok.split(':')
        kind, args = parts[0], parts[1:]
        lts, owner = m['lts'], m['from_id']
        A = m['atts']
        if kind == 'photo':
            A.append({'type': 'photo', 'photo': self.photo(owner, lts, args[0] if args else rng.choice(c.photo_kinds), rng)})
        elif kind == 'album':
            n = int(args[0]) if self.exact else max(2, int(args[0]) + rng.choice([-1, 0, 0, 1]))
            for _ in range(n):
                A.append({'type': 'photo', 'photo': self.photo(owner, lts, args[1], rng)})
        elif kind == 'sticker':
            A.append({'type': 'sticker', 'sticker': self.sticker(rng, args[0] if args else None)})
        elif kind == 'voice':
            tr = ':'.join(args) or self.voice_text(rng, c, owner)
            A.append({'type': 'audio_message', 'audio_message': self.voice(rng, owner, lts, tr)})
        elif kind == 'video':
            cat = args[0] if args else rng.choice(list(VIDEO_TITLES))
            title = ':'.join(args[1:]) or rng.choice(VIDEO_TITLES.get(cat, VIDEO_TITLES['nature']))
            A.append({'type': 'video', 'video': self.video(rng, owner, lts, cat, title)})
        elif kind == 'link':
            lk = self.link(rng, args[0], lts, ':'.join(args[1:]))
            A.append({'type': 'link', 'link': lk})
            if not self.exact and (rng.random() < 0.4 or not m['text']):
                m['text'] = (m['text'] + ' ' + urllib.parse.unquote(lk['url'])).strip()
        elif kind == 'doc':
            A.append({'type': 'doc', 'doc': self.doc(rng, owner, lts, args[0], ':'.join(args[1:]))})
        elif kind == 'poll':
            q, *answers = ':'.join(args).split('|')
            A.append({'type': 'poll', 'poll': self.poll(rng, c, owner, lts, q, answers)})
        elif kind == 'wall':
            A.append({'type': 'wall', 'wall': self.group_post(rng, args[0] if args else None, lts)})
        elif kind == 'fwd':
            m['fwd'] = self.forward(rng, c, m, args[0] if args else None)
        elif kind == 'reply':
            if args and args[0] == 'pending':
                m['reply'], self.pending_reply = getattr(self, 'pending_reply', None), None
                return
            cand = [h for h in reversed(history) if h['from_id'] != owner and (h['text'] or h['atts'])]
            if args and args[0] == 'self':
                cand = [h for h in reversed(history) if h['from_id'] == SELF_ID and h['text']]
            if cand:
                m['reply'] = cand[0]
        elif kind == 'call':
            other = c.peer if 0 < c.peer < 2000000000 else SELF_ID
            to = other if owner == SELF_ID else SELF_ID
            A.append({'type': 'call', 'call': {'initiator_id': owner, 'receiver_id': to, 'state': 'reached',
                                               'time': utc(lts), 'duration': rng.randint(40, 1500),
                                               'video': bool(args and args[0] == 'video') or rng.random() < 0.3}})
        elif kind == 'gift':
            A.append({'type': 'gift', 'gift': self.gift_obj(int(args[0]) if args else rng.choice(GIFT_IDS))})
            if m['peer'] > 0 and owner != SELF_ID:
                self.gifts_received.append((lts, owner, A[-1]['gift']['id'], m['text']))
        elif kind == 'audio':
            A.append({'type': 'audio', 'audio': self.music(rng, lts)})

    def voice_text(self, rng, c, owner):
        f = self.sex(owner) == 'f'
        key = 'f' if f else 'm'
        if owner == self.MOM:
            key = 'mom'
        elif owner == self.GRANDMA:
            key = 'grandma'
        elif c.kind == 'work' and rng.random() < 0.6:
            key = 'work'
        if rng.random() < 0.85:
            op, body, cl = VOICE_PARTS[key]
            o, bd = rng.choice(op), rng.choice(body)
            if o.endswith(('!', '.')):
                bd = bd[0].upper() + bd[1:]
            s = '%s %s' % (o, bd)
            end = rng.choice(cl)
            return s + ('. ' + end if end else '')
        key = c.voice
        if key == 'partner' and not f:
            key = 'partner_m'
        if key in ('friend', 'work') and f:
            key = 'generic_f'
        if key == 'friend_f' and not f:
            key = 'generic_m'
        if key in ('mom', 'grandma') and owner == SELF_ID:
            key = 'generic_m'
        if c.kind == 'family' and owner != self.GRANDMA:
            key = 'generic_f' if f else 'generic_m'
        return rng.choice(VOICE_TEXTS.get(key, VOICE_TEXTS['generic_m']))

    def photo_dims(self, rng, lts, size=None):
        if size is None:
            size = 1024 if lts > lts_of(date(2024, 3, 1)) else 800 if lts > lts_of(date(2021, 1, 1)) else 640
        r = rng.random()
        if r < 0.68:
            return size, size * 3 // 4
        if r < 0.9:
            return size * 3 // 4, size
        return size * 7 // 8, size * 7 // 8

    def cdn_url(self, rng, w, h):
        return 'https://sun9-%d.userapi.com/impg/%s/%s.jpg?size=%dx%d&quality=95&sign=%s&type=album' % (
            rng.randint(1, 88), rand_token(rng, 40), rand_token(rng, 11), w, h, rand_hex(rng, 32))

    def photo(self, owner, lts, kind, rng, size=None, dims=None, text='', album_id=-3):
        self.seq['photo'] += 1
        pid = self.seq['photo']
        key = '%d_%d' % (owner, pid)
        w, h = dims or self.photo_dims(rng, lts, size)
        rel = 'media/photos/%s.jpg' % key
        self.media['photo:' + key] = rel
        self.jobs.append(('scene', kind, stable_seed(self.seed, 'photo', key), w, h, rel, ldt(lts).month))
        url = self.cdn_url(rng, w, h)
        sizes = []
        for t, lim in (('s', 75), ('m', 130), ('x', 604), ('y', 807), ('z', 1080)):
            k = min(1.0, lim / max(w, h))
            sizes.append({'height': int(h * k), 'type': t, 'width': int(w * k), 'url': url.replace('size=%dx%d' % (w, h), 'size=%dx%d' % (int(w * k), int(h * k)))})
        return {'album_id': album_id, 'date': utc(lts), 'id': pid, 'owner_id': owner, 'access_key': rand_hex(rng, 18),
                'sizes': sizes, 'text': text, 'web_view_token': rand_hex(rng, 20), 'has_tags': False,
                'orig_photo': {'height': h, 'type': 'base', 'url': url, 'width': w}, '_link': url}

    def sticker(self, rng, emo=None):
        cand = [s for s in self.stickers if not emo or s['expr'] == emo] or self.stickers
        s = rng.choice(cand)
        sid = s['id']
        imgs = [{'url': 'https://vk.ru/sticker/1-%d-%d' % (sid, px), 'width': px, 'height': px} for px in (64, 128, 256, 352, 512)]
        return {'images': imgs, 'images_with_background': [dict(i, url=i['url'] + 'b') for i in imgs],
                'inner_type': 'base_sticker_new', 'is_allowed': True, 'product_id': s['product'], 'sticker_id': sid}

    def voice(self, rng, owner, lts, transcript):
        self.seq['doc'] += 1
        vid = self.seq['doc']
        key = '%d_%d' % (owner, vid)
        dur = max(2, int(len(transcript) / 13 + rng.uniform(0, 4)))
        self.media['voice:' + key] = 'media/voice/%s.mp3' % key
        self.files.append(('media/voice/%s.mp3' % key, 'voice', (stable_seed(self.seed, 'voice', key), min(dur, 3))))
        h = rand_hex(rng, 26)
        o = {'id': vid, 'owner_id': owner, 'duration': dur, 'access_key': rand_hex(rng, 18),
             'waveform': [rng.randint(0, 31) for _ in range(64)],
             'link_ogg': 'https://psv4.userapi.com/s/v1/amsg/%s.ogg' % h,
             'link_mp3': 'https://psv4.userapi.com/s/v1/amsg/%s.mp3' % h}
        if lts > lts_of(date(2021, 3, 1)):
            o.update(transcript=transcript, transcript_state='done')
        return o

    def video(self, rng, owner, lts, cat, title):
        self.seq['video'] += 1
        vid = self.seq['video']
        key = '%d_%d' % (owner, vid)
        scene = {'cat': 'cat', 'nature': rng.choice(['lake', 'forest', 'mountains', 'sea']), 'party': 'party',
                 'city': 'city', 'food': 'food'}.get(cat, cat)
        thumb = 'media/video_thumbs/%s.jpg' % key
        self.media['vthumb:' + key] = thumb
        self.jobs.append(('scene', scene, stable_seed(self.seed, 'video', key), 640, 360, thumb, ldt(lts).month))
        if self.ffmpeg:
            self.media['video:' + key] = 'media/videos/%s.mp4' % key
            self.files.append(('media/videos/%s.mp4' % key, 'video', (thumb,)))
        img = 'https://sun9-%d.userapi.com/impg/%s.jpg' % (rng.randint(1, 88), rand_token(rng, 30))
        return {'id': vid, 'owner_id': owner, 'title': title, 'duration': rng.randint(8, 190), 'description': '',
                'date': utc(lts), 'views': rng.randint(1, 40), 'comments': 0, 'type': 'video', 'can_add': 1,
                'access_key': rand_hex(rng, 18), 'is_from_message': 1,
                'image': [{'url': img + '?w=320', 'width': 320, 'height': 180}, {'url': img + '?w=640', 'width': 640, 'height': 360}],
                'files': {'mp4_360': 'https://vkvd%d.okcdn.ru/?id=%d' % (rng.randint(1, 500), rng.getrandbits(40))}}

    def link(self, rng, kind, lts, name=''):
        if kind == 'wiki':
            items = [x for x in LINKS['wiki'] if not name or x[0].startswith(name)] or LINKS['wiki']
            title, slug, scene = rng.choice(items)
            url, cap = 'https://ru.wikipedia.org/wiki/' + urllib.parse.quote(slug), 'ru.wikipedia.org'
        elif kind == 'youtube':
            items = [x for x in LINKS['youtube'] if not name or x[0].startswith(name)] or LINKS['youtube']
            title, scene = rng.choice(items)
            url, cap = 'https://www.youtube.com/watch?v=' + rand_token(rng, 11), 'youtube.com'
        elif kind in ('article', 'event'):
            title, gkey, scene = rng.choice(LINKS[kind])
            url, cap = 'https://vk.ru/@%s_demo-%s' % (gkey, rand_token(rng, 8, 'abcdefghijklmnopqrstuvwxyz')), 'vk.ru'
        elif kind == 'maps':
            title, scene = rng.choice(LINKS['maps']), None
            url, cap = 'https://yandex.ru/maps/-/C%s' % rand_token(rng, 7), 'yandex.ru'
        else:
            title, scene = rng.choice(LINKS['weather']), None
            url, cap = 'https://yandex.ru/pogoda/month?via=%s' % rand_token(rng, 5, 'abcdefghijklmnopqrstuvwxyz'), 'yandex.ru'
        o = {'url': url, 'title': title, 'caption': cap, 'is_favorite': False, 'target': 'internal'}
        if scene:
            o['photo'] = self.photo(LINK_OWNER, lts, scene, rng, dims=(640, 360))
        return o

    def doc(self, rng, owner, lts, ext, title):
        self.seq['doc'] += 1
        did = self.seq['doc']
        title = title or {'pdf': 'Документ.pdf', 'docx': 'Документ.docx', 'zip': 'Фото.zip', 'txt': 'Заметки.txt',
                          'gif': 'Котик.gif', 'jpg': 'IMG_%04d.jpg' % rng.randint(1000, 9999)}.get(ext, 'file.' + ext)
        dtype = {'pdf': 1, 'docx': 1, 'txt': 1, 'zip': 2, 'gif': 3, 'jpg': 4}.get(ext, 8)
        o = {'id': did, 'owner_id': owner, 'title': title, 'size': 0, 'ext': ext, 'date': utc(lts), 'type': dtype,
             'url': 'https://vk.ru/doc%d_%d?hash=%s&dl=%s' % (owner, did, rand_hex(rng, 18), rand_hex(rng, 18)),
             'access_key': rand_hex(rng, 18), 'is_licensed': 0, 'is_unsafe': 0, 'can_manage': owner == SELF_ID}
        rel = doc_path(o)
        self.media['doc:%d_%d' % (owner, did)] = rel
        o['size'] = {'pdf': 184320, 'docx': 48231, 'zip': 2457600, 'txt': 2048, 'gif': 412000, 'jpg': 230000}.get(ext, 10000) + rng.randint(0, 90000)
        if ext == 'jpg':
            self.jobs.append(('scene', 'landscape', stable_seed(self.seed, 'doc', did), 1024, 768, rel, ldt(lts).month))
        else:
            self.files.append((rel, 'doc', (ext, title, stable_seed(self.seed, 'doc', did))))
        if dtype == 1:
            o['_pdf'] = True
        self.docs[('%d_%d' % (owner, did))] = o
        return o

    def poll(self, rng, c, owner, lts, q, answers):
        self.seq['poll'] += 1
        n = len(c.pool) + 1 if c.pool else 2
        votes = [0] * len(answers)
        for _ in range(rng.randint(max(2, n // 2), n)):
            votes[min(len(answers) - 1, int(rng.triangular(0, len(answers), 0)))] += 1
        total = sum(votes)
        mine = next((i for i, a in enumerate(answers) if a.endswith('*')), rng.randrange(len(answers)))
        answers = [a.rstrip('*') for a in answers]
        votes[mine] += 1
        total += 1
        ans = [{'id': self.seq['poll'] * 10 + i, 'text': a, 'votes': v, 'rate': round(100.0 * v / total, 1)}
               for i, (a, v) in enumerate(zip(answers, votes))]
        return {'id': self.seq['poll'], 'owner_id': owner, 'created': utc(lts), 'question': q, 'votes': total,
                'answers': ans, 'anonymous': False, 'multiple': False, 'answer_ids': [ans[mine]['id']],
                'end_date': 0, 'closed': False, 'is_board': False, 'can_edit': False, 'can_vote': True,
                'can_report': False, 'can_share': True, 'author_id': owner, 'disable_unvote': False}

    def group_post(self, rng, key, lts):
        keys = [k for k in GROUP_PHOTOS if k not in ('polka', 'kolesa', 'afisha')]
        if key is None:
            keys = [k for k in keys if k != 'podslushano' or lts < lts_of(date(2019, 9, 1))]
            key = rng.choice(keys)
        gid = self.gid[key]
        t = lts - rng.randint(600, 86400 * 2)
        atts = [{'type': 'photo', 'photo': self.photo(-gid, t, rng.choice(GROUP_PHOTOS[key]), rng, size=800)}
                for _ in range(rng.choice([1, 1, 1, 2, 3]))]
        return {'id': rng.randint(1000, 90000), 'owner_id': -gid, 'from_id': -gid, 'date': utc(t),
                'text': rng.choice(GROUP_POSTS[key]), 'attachments': atts, 'post_type': 'post',
                'comments': {'count': rng.randint(0, 80)}, 'likes': {'count': rng.randint(10, 3000)},
                'reposts': {'count': rng.randint(0, 300)}, 'views': {'count': rng.randint(1000, 90000)}}

    def music(self, rng, lts):
        self.seq['audio'] += 1
        aid = self.seq['audio']
        artist, title = rng.choice(MUSIC)
        key = '%d_%d' % (SELF_ID, aid)
        self.media['audio:' + key] = 'media/audio/%s.mp3' % key
        self.files.append(('media/audio/%s.mp3' % key, 'voice', (stable_seed(self.seed, 'audio', key), 3)))
        return {'id': aid, 'owner_id': SELF_ID, 'artist': artist, 'title': title, 'duration': rng.randint(150, 260),
                'date': utc(lts), 'url': ''}

    def gift_obj(self, gid):
        self.need_gifts.add(gid)
        u = 'https://vk.ru/images/gift/%d/' % gid
        return {'id': gid, 'thumb_256': u + '256.png', 'thumb_96': u + '96.png', 'thumb_48': u + '48.png'}

    def forward(self, rng, c, m, preset=None, depth=0):
        t = m['lts']
        if preset == 'momcake':
            inner = {'from_id': self.DAD, 'lts': t - 7200, 'text': 'Сын, захвати удлинитель, если поедете', 'atts': [], 'fwd': []}
            return [{'from_id': self.MOM, 'lts': t - 3000, 'text': 'Приезжайте в субботу к обеду, я пирог испеку',
                     'atts': [{'type': 'photo', 'photo': self.photo(self.MOM, t - 3000, 'pie', rng)}], 'fwd': []},
                    {'from_id': self.MOM, 'lts': t - 2950, 'text': 'И папа просил передать:', 'atts': [], 'fwd': [inner]}]
        if preset == 'football':
            inner = {'from_id': self.PAVEL, 'lts': t - 9000, 'text': 'Я в деле, только к шести подъеду', 'atts': [], 'fwd': []}
            return [{'from_id': self.ARTEM, 'lts': t - 4000, 'text': 'Суббота: баня в 17:00, потом бар. Кто с нами?',
                     'atts': [], 'fwd': []},
                    {'from_id': self.ARTEM, 'lts': t - 3900, 'text': 'Паша уже согласился 😎', 'atts': [], 'fwd': [inner]}]
        if c.peer == self.KATYA:
            authors, cat = ([self.MOM, self.OLYA], 'mom') if m['from_id'] == SELF_ID else ([self.YULIA, self.ROMAN], 'friend')
        elif c.kind == 'work' or c.peer in (self.NIKITA, self.SVETA, self.KIRILL):
            authors, cat = [self.KIRILL] + self.work_pool, 'work'
        elif c.peer in (self.MOM, self.DAD, self.OLYA) or c.kind == 'family':
            authors, cat = [self.AUNT, self.GRANDMA, self.MAX], 'any'
        elif c.kind == 'uni' or (c.peer in (self.ANNA, self.DENIS) and t < lts_of(date(2019, 7, 1))):
            authors, cat = self.uni_pool[:6], 'uni'
        else:
            authors, cat = [self.DIMA, self.PAVEL, self.ARTEM, self.MASHA] + self.extra_friends[:5], 'friend'
        authors = [a for a in authors if a != m['from_id'] and a != self.deleted] or [self.DIMA]
        a = rng.choice(authors)
        n = rng.choice([1, 1, 1, 2, 2, 3])
        t0 = t - rng.randint(120, 86400 * 3)
        out = []
        for i in range(n):
            f = {'from_id': a, 'lts': t0 + i * rng.randint(10, 200), 'text': rng.choice(FWD_TEXTS[cat]), 'atts': [], 'fwd': []}
            if rng.random() < 0.2:
                f['atts'].append({'type': 'photo', 'photo': self.photo(a, f['lts'], rng.choice(['landscape', 'food', 'cat', 'city', 'flowers']), rng)})
            out.append(f)
        if depth < 2 and rng.random() < 0.18:
            out[0]['fwd'] = self.forward(rng, c, {'lts': t0, 'from_id': a}, None, depth + 1)
        return out


