class Content:
    """Mixin: everything beyond the random daily chatter."""

    def conv(self, peer):
        return next(c for c in self.convs if c.peer == peer)

    def scripted(self, rng, c, text, t0):
        return self.play(rng, c, parse_scenes(text)[0], t0, self.msgs[c.peer])

    def add_specials(self):
        rng = random.Random(stable_seed(self.seed, 'specials'))
        active = lambda c, d: c.start <= d <= c.end and lts_of(d, 23) < EXPORT_TS

        def add(c, key, d, hour, minute=None):
            if not active(c, d):
                return
            t0 = lts_of(d, hour, rng.randint(0, 59) if minute is None else minute, rng.randint(0, 59))
            self.msgs[c.peer].extend(m for m in self.scripted(rng, c, SPECIAL[key], t0) if m['lts'] < EXPORT_TS - 1800)

        for y in range(2014, 2027):
            bd = date(y, 3, 17)
            for c in self.convs:
                p, k = c.peer, c.kind
                if p == self.KATYA:
                    add(c, 'bday_partner', bd, 0, 1)
                elif p == self.MOM:
                    add(c, 'bday_mom', bd, 8)
                elif p == self.GRANDMA:
                    add(c, 'bday_grandma', bd, 10)
                elif p in (self.SUPER, self.LANDLORD, self.BUYER):
                    continue
                elif p in (self.DAD, self.OLYA, self.DIMA, self.MAX) or (k == 'personal' and rng.random() < 0.45) or \
                        (k == 'work' and 0 < p < 2000000000 and rng.random() < 0.5):
                    add(c, 'bday', bd, rng.choice([9, 10, 12, 14, 18, 20]))
                elif k == 'family':
                    add(c, 'bday_family', bd, 9)
                elif k == 'work' and p >= 2000000000 and bd.weekday() < 5:
                    add(c, 'bday_work', bd, 11)
                elif k == 'uni' and y <= 2019:
                    add(c, 'bday_uni', bd, 12)
                elif k == 'hike':
                    add(c, 'bday_hike', bd, 19)
            ny = date(y - 1, 12, 31)
            for c in self.convs:
                if c.kind in ('bot', 'news', 'work') and c.peer > 0:
                    continue
                if c.kind in ('bot', 'news'):
                    continue
                if c.peer == self.KATYA:
                    add(c, 'ny_partner', date(y, 1, 1), 0, 0)
                elif c.kind == 'family':
                    add(c, 'ny_family', ny, 23, rng.randint(40, 58))
                elif c.peer >= 2000000000:
                    add(c, 'ny_group', date(y, 1, 1), 0, rng.randint(0, 20))
                elif rng.random() < 0.55:
                    add(c, 'ny', ny if rng.random() < 0.4 else date(y, 1, 1), rng.choice([0, 12, 19, 22]))
            for p, key in ((self.KATYA, 'march8_partner'), (self.MOM, 'march8'), (self.OLYA, 'march8'), (self.GRANDMA, 'march8')):
                add(self.conv(p), key, date(y, 3, 8), rng.choice([8, 9, 10, 11]))
            for p in (self.MOM, self.OLYA, self.KATYA):
                if rng.random() < 0.8:
                    add(self.conv(p), 'feb23', date(y, 2, 23), rng.choice([9, 12, 18]))
            add(self.conv(self.KATYA), 'bday_katya', date(y, 8, 9), 0, 0)
            add(self.conv(self.MOM), 'bday_mom2', date(y, 11, 2), 8)
            add(self.conv(2000000003), 'bday_mom_family', date(y, 11, 2), 9)

    def add_showcases(self):
        self.exact = True
        for c in self.convs:
            if not c.showcase:
                continue
            rng = random.Random(stable_seed(self.seed, 'showcase', c.peer))
            roles = self.roles_for(rng, c, [(L, '') for L in 'ABCDHLMPSGKOX'])
            if c.peer < 2000000000:
                roles.update(O=SELF_ID, X=c.peer)
            else:
                roles['O'] = SELF_ID
                roles.update(c.roles)
                free = [m for m in c.pool if m not in c.roles.values()]
                if free:
                    roles.update(A=free[0], B=free[1 % len(free)], C=free[2 % len(free)], D=free[3 % len(free)])
            for ln in SHOWCASE[c.showcase].strip().split('\n'):
                m = re.match(r'(\S+) (\d+):(\d+) (\w): (.*)', ln)
                d = date.fromisoformat(m.group(1))
                t = lts_of(d, int(m.group(2)), int(m.group(3)), rng.randint(0, 59))
                msg = self.make_msg(rng, c, roles[m.group(4)], t, self.find_reply(m.group(5), c), self.msgs[c.peer])
                if msg:
                    self.msgs[c.peer].append(msg)
        self.exact = False

    def find_reply(self, text, c):
        """<<reply:find:substring>> -> a reply to the newest message containing it."""
        m = re.search(r'<<reply:find:([^>]*)>>', text)
        if not m:
            return text
        for h in reversed(self.msgs[c.peer]):
            if m.group(1) in h['text']:
                self.pending_reply = h
                break
        return text.replace(m.group(0), '<<reply:pending>>')

    def srv(self, peer, actor, d, h, mi, html_text):
        self.msgs[peer].append({'peer': peer, 'from_id': actor, 'lts': lts_of(d, h, mi, random.Random(stable_seed(peer, d, h, mi)).randint(0, 59)),
                                'text': '', 'atts': [], 'fwd': [], 'reply': None, 'service': html_text, 'edited': None})

    def srv_link(self, uid):
        return '<a class="im_srv_lnk " target="_blank" href="https://vk.ru/id%d">%s</a>' % (uid, enc(self.name(uid)))

    def add_services(self):
        verb = lambda uid, m, f: f if self.sex(uid) == 'f' else m
        L = self.srv_link
        for peer, old, new, change in ((2000000001, 'ПМИ-15', 'ПМИ-15 🎓', date(2016, 9, 1)),
                                       (2000000002, 'Походы', 'Походы 🏕', date(2018, 6, 2)),
                                       (2000000003, 'Семья', 'Семья ❤️', date(2019, 4, 3)),
                                       (2000000005, 'Футбол по средам', 'Футбол по средам ⚽', date(2016, 4, 6)),
                                       (2000000006, 'Квартира на Лесной', None, None)):
            ch = self.chats[peer]
            c = self.conv(peer)
            admin, d0 = ch['admin'], c.start
            t0 = lts_of(d0, 9, 0)
            self.msgs[peer] = [m for m in self.msgs[peer] if m['lts'] >= t0 + 600]
            self.srv(peer, admin, d0, 9, 0, '%s %s чат «%s»' % (L(admin), verb(admin, 'создал', 'создала'), enc(old)))
            for k, u in enumerate([SELF_ID] + [x for x in ch['members'] if x != admin]):
                if u == self.KATYA and peer == 2000000002:
                    continue
                if peer == 2000000005 and k > 3:
                    self.srv(peer, u, d0 + timedelta(k // 2), 20, k, '%s %s к чату по ссылке' % (L(u), verb(u, 'присоединился', 'присоединилась')))
                elif u != admin:
                    self.srv(peer, admin, d0, 9, 1 + k, '%s %s %s' % (L(admin), verb(admin, 'пригласил', 'пригласила'), L(u)))
            if change:
                who = self.MOM if peer == 2000000003 else admin
                self.srv(peer, who, change, 21 if peer != 2000000003 else 9, 30, '%s %s название чата: «%s» &rarr; «%s»' % (
                    L(who), verb(who, 'изменил', 'изменила'), enc(old), enc(new)))
        P = self.PAVEL
        self.srv(2000000002, P, date(2018, 6, 2), 21, 20, '%s пригласил %s' % (L(P), L(self.KATYA)))
        A = self.ANNA
        self.srv(2000000001, A, date(2017, 2, 6), 10, 15, '%s закрепила сообщение «Расписание на весну — в документе»' % L(A))
        x = self.uni_pool[3]
        self.srv(2000000001, x, date(2016, 2, 10), 18, 2, '%s %s из чата' % (L(x), verb(x, 'вышел', 'вышла')))
        x = self.uni_pool[5]
        self.srv(2000000001, A, date(2018, 9, 3), 12, 40, '%s исключила %s' % (L(A), L(x)))
        K = self.KIRILL
        self.msgs[2000000004] = [m for m in self.msgs[2000000004] if m['lts'] >= lts_of(date(2021, 3, 15), 10, 10)]
        self.srv(2000000004, K, date(2021, 3, 15), 10, 5, '%s пригласил %s' % (L(K), L(SELF_ID)))
        x = self.work_pool[4]
        self.srv(2000000004, x, date(2024, 2, 1), 17, 50, '%s %s из чата' % (L(x), verb(x, 'вышел', 'вышла')))
        self.srv(2000000004, K, date(2024, 2, 5), 10, 12, '%s закрепил сообщение «Релизы — по вторникам и четвергам»' % L(K))
        x = self.foot_pool[2]
        self.srv(2000000005, x, date(2019, 5, 15), 22, 10, '%s %s из чата' % (L(x), verb(x, 'вышел', 'вышла')))
        self.srv(2000000005, x, date(2019, 6, 1), 13, 3, '%s %s в чат' % (L(x), verb(x, 'вернулся', 'вернулась')))

    def finalize(self):
        allm = []
        for peer in list(self.msgs):
            lst = [m for m in self.msgs[peer] if m['from_id'] != SELF_ID or not self.offline(ldt(m['lts']).date())]
            lst.sort(key=lambda m: m['lts'])
            self.msgs[peer] = lst
            allm.extend(lst)
        allm.sort(key=lambda m: (m['lts'], m['peer']))
        for i, m in enumerate(allm):
            m['id'] = 1200 + i
        for lst in self.msgs.values():
            for k, m in enumerate(lst, 1):
                m['cmid'] = k

    # -- photos for the profile sections --
    def owner_photo_seed(self):
        return stable_seed(self.seed, 'owner-avatar')

    def build_albums(self):
        rng = random.Random(stable_seed(self.seed, 'albums'))
        A = []

        def spread(d0, days, n):
            return sorted(lts_of(d0 + timedelta(rng.randrange(days)), rng.randint(7, 22), rng.randint(0, 59), rng.randint(0, 59)) for _ in range(n))

        prof = []
        for i, (d, kind) in enumerate([(date(2014, 4, 2), 'city'), (date(2016, 7, 20), 'mountains'), (date(2018, 9, 1), 'sea'),
                                       (date(2020, 6, 14), 'forest'), (date(2023, 2, 12), 'winter'), (date(2025, 8, 3), 'mountains')]):
            lts = lts_of(d, 20, 15)
            p = self.photo(SELF_ID, lts, kind, rng, dims=(800, 800), album_id=-6)
            if i == 5:  # the current avatar is this picture
                self.jobs[-1] = ('scene', kind, self.owner_photo_seed(), 800, 800, self.jobs[-1][5], 8)
            prof.append(p)
        A.append((-6, 'Фото профиля', prof))
        A.append((-7, 'Фото на стене', [a['photo'] for p in self.wall_posts for a in p['attachments'] if a['type'] == 'photo']))
        saved = [self.photo(SELF_ID, t, rng.choice(['cat', 'space', 'landscape', 'food', 'city', 'mountains']), rng, size=800, album_id=-15)
                 for t in spread(date(2015, 1, 1), 4000, 18)]
        A.append((-15, 'Сохранённые фото', saved))
        user_albums = [(250000001, 'Байкал, 2019', date(2019, 7, 6), 12, 30, ['lake', 'mountains', 'forest', 'campfire', 'space', 'sunset']),
                       (250000002, 'Карелия, 2021', date(2021, 7, 10), 10, 22, ['forest', 'lake', 'campfire', 'landscape']),
                       (250000003, 'Новый год', date(2019, 12, 31), 1, 12, ['party', 'winter', 'citynight', 'cake', 'bokeh']),
                       (250000004, 'Еда', date(2018, 3, 1), 2900, 16, ['food', 'coffee', 'pie', 'pizza', 'sushi'])]
        for aid, title, d0, days, n, kinds in user_albums:
            ph = []
            for t in spread(d0, days, n):
                if aid == 250000003:
                    t = lts_of(date(rng.randint(2016, 2025), 12, 31), rng.randint(19, 23), rng.randint(0, 59))
                ph.append(self.photo(SELF_ID, t, rng.choice(kinds), rng, size=1024 if aid < 250000003 else 800, album_id=aid))
            ph.sort(key=lambda p: p['date'])
            A.append((aid, title, ph))
        self.albums = A
        self.album_comments = {}
        for aid, title, ph in A:
            if not ph:
                continue
            for p in rng.sample(ph, min(len(ph), 2 if aid in (250000001, -6, 250000002) else 0)):
                cs = []
                t = p['date'] + TZ
                for k in range(rng.randint(1, 3)):
                    t += rng.randint(300, 40000)
                    who = rng.choice([self.KATYA, self.DIMA, self.MOM, self.OLYA, self.PAVEL, SELF_ID if k else self.MAX])
                    cs.append({'id': rng.randint(1000, 9000), 'from_id': who, 'date': utc(t),
                               'text': rng.choice(['Красота!', 'Где это?', 'Вау 😍', 'Огонь', 'Спасибо!' if who == SELF_ID else 'Класс!', 'Хочу туда'])})
                self.album_comments[p['id']] = (aid, title, cs)

    def build_wall(self):
        rng = random.Random(stable_seed(self.seed, 'wall'))
        own = [(date(2014, 3, 2), 'Весна? Не, не слышал ❄️', ['winter']),
               (date(2014, 7, 12), 'Лето на даче', ['garden', 'garden']),
               (date(2014, 9, 1), 'Одиннадцатый класс. Последний рывок', ['city']),
               (date(2015, 1, 1), 'С Новым годом, друзья! 🎄', ['party']),
               (date(2015, 6, 27), 'Выпускной! Школа, прощай 🎓', ['party', 'party', 'city']),
               (date(2015, 9, 1), 'Первый курс, поехали!', ['city']),
               (date(2016, 7, 3), 'Первый поход в горы. Ноги болят, но оно того стоило ⛰', ['mountains', 'mountains', 'campfire', 'lake']),
               (date(2017, 7, 24), 'Неделя без связи, костры и звёзды', ['campfire', 'forest', 'space']),
               (date(2018, 1, 1), 'С Новым годом! Пусть он будет добрым 🎄', ['party']),
               (date(2018, 8, 12), 'Карелия ❤️', ['lake', 'forest', 'lake']),
               (date(2019, 6, 28), 'Диплом защищён! Спасибо всем, кто поддерживал 🎓', ['city']),
               (date(2019, 7, 18), 'Байкал, ты прекрасен 🌊', ['lake', 'mountains', 'lake', 'sunset']),
               (date(2020, 4, 12), 'Самоизоляция, день 14. Научился печь хлеб', ['food', 'food']),
               (date(2021, 3, 15), 'Первый день на новой работе!', ['city']),
               (date(2021, 7, 20), 'Карелия, часть вторая', ['forest', 'lake', 'campfire']),
               (date(2022, 9, 25), 'Пробежал первый полумарафон 🏃 21,1 км, 2:04:31', ['city']),
               (date(2023, 5, 19), 'Продаю велосипед, в хорошем состоянии, пишите в личку', ['bike']),
               (date(2024, 7, 21), 'Хибины летом — это отдельная любовь', ['mountains', 'mountains', 'lake', 'mountains']),
               (date(2025, 1, 1), 'С Новым годом! 🎄', ['party']),
               (date(2025, 7, 28), 'Алтай. Слов нет, только фото', ['mountains', 'lake', 'mountains', 'sunset']),
               (date(2026, 7, 19), 'Снова в горах ⛰', ['mountains', 'campfire', 'space'])]
        reposts = []
        for _ in range(32):
            y = rng.choices(range(2014, 2027), [8, 8, 7, 6, 4, 3, 3, 2, 1, 1, 2, 2, 2])[0]
            d = date(y, 1, 1) + timedelta(rng.randrange(365))
            if d < LAST_DAY:
                reposts.append(d)
        items = [(d, 'own', x) for d, *x in own] + [(d, 'repost', None) for d in reposts]
        items.sort(key=lambda x: x[0])
        posts, comments, pid = [], {}, 3
        commenters = [self.KATYA, self.DIMA, self.MOM, self.OLYA, self.PAVEL, self.ANNA, self.DENIS, self.MASHA, self.MAX] + self.extra_friends[:8]
        for d, kind, x in items:
            pid += rng.randint(1, 14)
            lts = lts_of(d, rng.randint(10, 22), rng.randint(0, 59), rng.randint(0, 59))
            post = {'id': pid, 'owner_id': SELF_ID, 'from_id': SELF_ID, 'date': utc(lts), 'text': '', 'attachments': [],
                    'post_type': 'post', 'comments': {'count': 0}, 'likes': {'count': rng.randint(3, 60)},
                    'reposts': {'count': rng.randint(0, 3)}, 'views': {'count': rng.randint(80, 900)}, '_lts': lts}
            if kind == 'own':
                post['text'] = x[0]
                post['attachments'] = [{'type': 'photo', 'photo': self.photo(SELF_ID, lts, k, rng, size=800, album_id=-7)} for k in x[1]]
            else:
                post['copy_history'] = [self.group_post(rng, None, lts)]
            if kind == 'own' and rng.random() < 0.75 or kind != 'own' and rng.random() < 0.15:
                cs, t = [], lts
                pool = [u for u in commenters if self.conv_active(u, d)]
                for k in range(rng.randint(1, 5)):
                    t += rng.randint(200, 20000)
                    who = rng.choice(pool) if pool else self.DIMA
                    text = rng.choice(['Красота!', 'Где это?', 'Поздравляю!! 🎉', 'Круто!', 'Завидую', 'Вау', 'Ты молодец!',
                                       'Фото огонь 🔥', 'Когда снова?', '❤️', 'Ахаха', 'Класс!'])
                    cid = pid * 10 + k + 1
                    cs.append({'id': cid, 'from_id': who, 'date': utc(t), 'text': text, 'owner_id': SELF_ID, 'post_id': pid,
                               'parents_stack': []})
                    if rng.random() < 0.4:
                        t += rng.randint(100, 3000)
                        cs.append({'id': cid + 5, 'from_id': SELF_ID, 'date': utc(t), 'owner_id': SELF_ID, 'post_id': pid,
                                   'text': rng.choice(['Спасибо!', 'Спасибо)', 'Скоро!', 'В следующий раз вместе поедем', '😊']),
                                   'reply_to_user': who, 'reply_to_comment': cid, 'parents_stack': []})
                comments[pid] = [c for c in cs if c['date'] + TZ < EXPORT_TS]
                post['comments']['count'] = len(comments[pid])
            posts.append(post)
        self.wall_posts = posts
        self.wall_comments = comments

    def conv_active(self, uid, d):
        for c in self.convs:
            if c.peer == uid:
                return c.start <= d <= c.end
        return True

    def build_likes(self):
        rng = random.Random(stable_seed(self.seed, 'likes'))
        likes = {k: {} for k in ('photo', 'wall', 'video', 'wall_reply', 'photo_comment', 'video_comment', 'topic_comment', 'market')}
        order = {k: [] for k in likes}

        def when():
            while True:
                y = rng.choices(range(2014, 2027), [9, 9, 8, 7, 6, 5, 6, 4, 2, 2, 3, 4, 4])[0]
                t = lts_of(date(y, 1, 1) + timedelta(rng.randrange(365)), rng.randint(8, 23), rng.randint(0, 59))
                if t < EXPORT_TS - 86400:
                    return t
        friends = self.friend_ids()
        groups = [k for k in GROUP_PHOTOS if k not in ('kolesa', 'polka')]
        for _ in range(140):
            t = when()
            if rng.random() < 0.7:
                key = rng.choice(groups)
                p = self.photo(-self.gid[key], t, rng.choice(GROUP_PHOTOS[key]), rng, size=640)
                p['user_id'] = 100
            else:
                u = rng.choice(friends)
                p = self.photo(u, t, rng.choice(['landscape', 'cat', 'food', 'city', 'flowers', 'party', 'sunset']), rng, size=640)
            k = '%d_%d' % (p['owner_id'], p['id'])
            likes['photo'][k] = p
            order['photo'].append((t, 'https://vk.ru/photo' + k))
        for _ in range(110):
            t = when()
            if rng.random() < 0.75:
                post = self.group_post(rng, None, t)
                post['date'] = utc(t - rng.randint(60, 3600))
            else:
                u = rng.choice(friends)
                post = {'id': rng.randint(10, 3000), 'owner_id': u, 'from_id': u, 'date': utc(t - rng.randint(60, 3600)),
                        'text': expand(rng, rng.choice(FRIEND_POSTS), self.sex(u) == 'f'), 'post_type': 'post',
                        'attachments': [{'type': 'photo', 'photo': self.photo(u, t, rng.choice(['landscape', 'party', 'food', 'cat', 'city']), rng, size=640)}
                                        for _ in range(rng.choice([0, 1, 1, 2]))],
                        'comments': {'count': rng.randint(0, 9)}, 'likes': {'count': rng.randint(5, 90)}}
            k = '%d_%d' % (post['owner_id'], post['id'])
            likes['wall'][k] = post
            order['wall'].append((t, 'https://vk.ru/wall' + k))
        for _ in range(28):
            t = when()
            key = rng.choice(list(GROUP_VIDEOS))
            cat, titles = GROUP_VIDEOS[key]
            v = self.video(rng, -self.gid[key], t, cat, rng.choice(titles))
            k = '%d_%d' % (v['owner_id'], v['id'])
            self.media.pop('video:' + k, None)
            self.files = [f for f in self.files if f[0] != 'media/videos/%s.mp4' % k]
            v['views'] = rng.randint(2000, 400000)
            likes['video'][k] = v
            order['video'].append((t, 'https://vk.ru/video' + k))
        for kind, n, rx in (('wall_reply', 40, 'wall'), ('photo_comment', 12, 'photo'), ('video_comment', 5, 'video'), ('topic_comment', 6, 'topic')):
            for _ in range(n):
                t = when()
                key = rng.choice(groups)
                obj, cid = rng.randint(100, 90000), rng.randint(1000, 990000)
                author = rng.choice(self.strangers[14:])
                c = {'id': cid, 'from_id': author, 'date': utc(t - rng.randint(60, 7200)), 'text': rng.choice(COMMENT_TEXTS)}
                if kind == 'wall_reply':
                    c.update(owner_id=-self.gid[key], post_id=obj)
                k = '%d_%d_%d' % (-self.gid[key], obj, cid)
                likes[kind][k] = c
                order[kind].append((t, 'https://vk.ru/%s%d_%d?reply=%d' % (rx, -self.gid[key], obj, cid)))
        for title, price in (('«Сто лет одиночества», подарочное издание', '1 290 ₽'), ('Блокнот в клетку, A5', '390 ₽')):
            t = when()
            url = 'https://sun9-%d.userapi.com/impg/%s.jpg?size=400x400' % (rng.randint(1, 88), rand_token(rng, 30))
            rel = 'media/misc/%s.jpg' % hashlib.sha1(url.encode()).hexdigest()[:16]
            self.media['url:' + hashlib.sha1(url.encode()).hexdigest()[:16]] = rel
            self.jobs.append(('scene', 'books', stable_seed(self.seed, 'market', title), 400, 400, rel, 5))
            iid = rng.randint(100, 9000)
            k = '%d_%d' % (-self.gid['polka'], iid)
            likes['market'][k] = {'id': iid, 'owner_id': -self.gid['polka'], 'title': title, 'price': {'text': price}, 'thumb_photo': url}
            order['market'].append((t, 'https://vk.ru/market?w=product' + k))
        for k in order:
            order[k].sort(reverse=True)
        self.likes, self.like_order = likes, order

    def build_my_comments(self):
        rng = random.Random(stable_seed(self.seed, 'mycomments'))
        out = []
        for _ in range(152):
            y = rng.choices(range(2014, 2027), [12, 12, 10, 8, 6, 5, 5, 3, 2, 2, 3, 3, 3])[0]
            t = lts_of(date(y, 1, 1) + timedelta(rng.randrange(365)), rng.randint(8, 23), rng.randint(0, 59))
            if t > EXPORT_TS - 86400:
                continue
            key = rng.choice([k for k in GROUP_PHOTOS if k not in ('kolesa', 'polka')])
            gid = self.gid[key]
            post, cid = rng.randint(100, 90000), rng.randint(1000, 990000)
            c = {'id': cid, 'from_id': SELF_ID, 'date': utc(t), 'text': rng.choice(MY_COMMENTS), 'owner_id': -gid, 'post_id': post,
                 'parents_stack': [], 'attachments': []}
            if rng.random() < 0.08:
                c['attachments'].append({'type': 'photo', 'photo': self.photo(SELF_ID, t, rng.choice(GROUP_PHOTOS[key]), rng, size=640)})
            thread = rng.random() < 0.12
            out.append((t, c, thread))
        out.sort(key=lambda x: -x[0])
        self.my_comments = out

    def build_extras(self):
        """Gifts sent from profiles and files uploaded to "Документы" outside of chats."""
        rng = random.Random(stable_seed(self.seed, 'extras'))
        for uid, d, text in ((self.DIMA, date(2016, 3, 17), 'С днюхой!'), (self.OLYA, date(2017, 12, 31), 'С Новым годом! 🎄'),
                             (self.MASHA, date(2015, 3, 17), ''), (self.ANNA, date(2018, 3, 17), 'С днём рождения!'),
                             (self.PAVEL, date(2022, 3, 17), ''), (self.YULIA, date(2021, 12, 31), 'С наступающим! ✨'),
                             (self.MAX, date(2019, 3, 17), 'Братишка, с днём рождения!'), (self.extra_friends[0], date(2020, 3, 17), ''),
                             (self.OLYA, date(2024, 2, 23), 'С 23 февраля 😊'), (self.DIMA, date(2025, 12, 31), '')):
            self.gifts_received.append((lts_of(d, rng.randint(9, 22), rng.randint(0, 59)), uid, rng.choice(GIFT_IDS), text))
        for ext, title, d in (('pdf', 'Резюме_Смирнов_2021.pdf', date(2021, 2, 10)), ('zip', 'Фото с Байкала.zip', date(2019, 7, 25)),
                              ('gif', 'Котик.gif', date(2018, 5, 5)), ('docx', 'Список покупок на дачу.docx', date(2020, 5, 1)),
                              ('txt', 'Заметки к походу.txt', date(2017, 6, 30)), ('pdf', 'Диплом участника полумарафона.pdf', date(2022, 9, 26)),
                              ('jpg', 'IMG_2041.jpg', date(2016, 8, 1)), ('pdf', 'Договор аренды.pdf', date(2019, 8, 19))):
            self.doc(rng, SELF_ID, lts_of(d, rng.randint(9, 22), rng.randint(0, 59)), ext, title)

    def build_support(self):
        """A few requests to VK support (vk_archive_enrich saves these conversations too)."""
        agent_ava = 'https://vk.ru/images/support_agent_demo.png'
        self.users[SELF_ID]['_photo'] = self.avatar_url(random.Random(stable_seed(self.seed, 'self-ava')), SELF_ID)
        self.support_avatars = {agent_ava: ('logo', 'support')}
        me = '%s %s' % (self.users[SELF_ID]['first'], self.users[SELF_ID]['last'])
        shot = 'https://sun9-%d.userapi.com/impg/support_demo_%d.png' % (31, 1)
        self.support_shots = {shot: 'uimock'}
        T = [(30210457, 'Не приходит код подтверждения', date(2019, 3, 4), 'Вопрос решён', [
                 ('me', 'Здравствуйте! Пытаюсь войти с нового телефона, но SMS с кодом не приходит уже второй день. Номер правильный.'),
                 ('agent', 'Здравствуйте, Алексей!<br>Попробуйте, пожалуйста, запросить звонок вместо SMS — на экране ввода кода '
                           'есть кнопка <b>«Позвонить»</b>. Если не поможет, напишите нам ещё раз.'),
                 ('me', 'Со звонком получилось, спасибо!'),
                 ('agent', 'Рады помочь! Хорошего дня 😊')]),
             (30388120, 'Как восстановить удалённую переписку?', date(2021, 11, 22), 'Вопрос решён', [
                 ('me', 'Добрый вечер. Случайно удалил переписку с другом, можно ли её как-то вернуть?'),
                 ('agent', 'Здравствуйте!<br>К сожалению, удалённые сообщения восстановить нельзя: после удаления они '
                           'пропадают с наших серверов. Но у вашего собеседника переписка осталась — он может переслать вам '
                           'нужные сообщения.'),
                 ('me', 'Понял, спасибо за ответ')]),
             (30555902, 'Не загружаются фотографии в альбом', date(2024, 4, 15), 'Вопрос решён', [
                 ('me', 'Здравствуйте! При загрузке фотографий в альбом появляется ошибка, прикладываю скриншот.'),
                 ('agent', 'Здравствуйте, Алексей!<br>Спасибо за скриншот. Мы исправили ошибку — пожалуйста, попробуйте '
                           'загрузить фотографии ещё раз.'),
                 ('me', 'Всё заработало, спасибо!')])]
        self.support = {}
        rng = random.Random(stable_seed(self.seed, 'support'))
        for tid, title, d, status, rows in T:
            t = t_first = lts_of(d, rng.randint(10, 20), rng.randint(0, 59))
            agent = 'Агент поддержки №%d' % rng.randint(100, 999)
            replies = []
            for who, text in rows:
                replies.append({'author': me if who == 'me' else agent,
                                'mine': who == 'me', 'avatar': self.users[SELF_ID]['_photo'] if who == 'me' else agent_ava,
                                'date': list_date(t), 'text': text.replace('\n', '<br>'), 'fields': [],
                                'attachments': [{'href': shot, 'thumb': shot, 'name': 'Скриншот.png'}]
                                if who == 'me' and 'скриншот' in text else []})
                t += rng.randint(3600, 86400)
            self.support[str(tid)] = {'title': title, 'status': status, 'replies': replies, 'fetched': EXPORT_TS - TZ + 3600,
                                      '_lts': t_first}

    def friend_ids(self):
        main = [self.KATYA, self.DIMA, self.MOM, self.DAD, self.OLYA, self.GRANDMA, self.MAX, self.ANNA, self.DENIS, self.PAVEL,
                self.MASHA, self.ARTEM, self.NIKITA, self.KIRILL, self.SVETA, self.YULIA, self.ROMAN, self.ALINA, self.AUNT]
        others = [u for u in self.uni_pool if u != self.deleted][:8] + self.work_pool[:3] + self.hike_pool + self.foot_pool[:4]
        return main + others + self.extra_friends

    def build_stickers(self):
        packs = [('blob', 101), ('cat', 102), ('bear', 103), ('bunny', 104), ('chick', 105)]
        exprs = ['happy', 'love', 'laugh', 'sad', 'wow', 'thumb', 'sleep', 'angry']
        sid = 6000
        for char, prod in packs:
            for e in exprs:
                sid += 1
                self.stickers.append({'id': sid, 'product': prod, 'char': char, 'expr': e})
                rel = 'media/stickers/%d.png' % sid
                self.media['sticker:%d' % sid] = rel
                self.jobs.append(('sticker', char, stable_seed(self.seed, 'sticker', sid), 256, 256, rel, e))


