def crumb_link(href, label):
    return '<a class="ui_crumb" href="%s" data-testid="header_link_crumb">%s</a><div class="ui_crumb_sep"></div>' % (href, enc(label))


def crumbs(links, last):
    return ''.join(crumb_link(h, label) for label, h in links) + '<div class="ui_crumb" >%s</div>' % enc(last)


def pagination(names, cur):
    if len(names) < 2:
        return ''
    lo, hi = max(0, cur - 2), min(len(names) - 1, cur + 2)

    def a(i, label):
        return '<a class="pg_lnk%s fl_l" href="%s".html><div class="pg_in">%s</div></a>' % ('_sel' if i == cur else '', names[i], label)
    parts = ([a(0, '&laquo;')] if lo > 0 else []) + [a(i, str(i + 1)) for i in range(lo, hi + 1)] + \
        ([a(len(names) - 1, '&raquo;')] if hi < len(names) - 1 else [])
    return '<div class="pagination clear_fix">\n  <div class="fl_r">\n    %s\n  </div>\n</div>' % ''.join(parts)


def stub_html(text):
    return '<div class="nothing-found-stub">\n  <div class="nothing-found-stub__text">%s</div>\n</div>' % enc(text)


def item(main, tertiary=None, sep='\n  \n  '):
    t = "<div class='item__tertiary'>%s</div>" % tertiary if tertiary is not None else ''
    return '<div class="item">\n  <div class=\'item__main\'>%s</div>%s%s\n</div>' % (main, sep, t)


def att_stub(desc, href=None, text=None):
    link = "<a class='attachment__link' href='%s'>%s</a>" % (href, text or href) if href else ''
    return '<div class="attachment">\n  <div class="attachment__description">%s</div>\n  %s\n</div>' % (desc, link)


def fwd_label(n):
    return '%d %s' % (n, plural(n, ('прикреплённое сообщение', 'прикреплённых сообщения', 'прикреплённых сообщений')))


def oid(o):
    return '%s_%s' % (o['owner_id'], o['id'])


def stubs_of(atts):
    out = []
    for a in atts:
        t, o = a['type'], a[a['type']]
        if t == 'photo':
            out.append(att_stub('Фотография', o['_link']))
        elif t == 'video':
            out.append(att_stub('Видеозапись', 'https://vk.ru/video' + oid(o)))
        elif t == 'doc':
            out.append(att_stub('Файл', 'https://vk.ru/doc' + oid(o)))
        elif t == 'audio_message':
            out.append(att_stub('Файл', o['link_ogg'], 'https://vk.ru/doc' + oid(o)))
        elif t == 'link':
            out.append(att_stub('Ссылка', enc(o['url'])))
        else:
            out.append(att_stub({'sticker': 'Стикер', 'wall': 'Запись на стене', 'poll': 'Опрос', 'gift': 'Подарок',
                                 'call': 'Звонок', 'audio': 'Аудиозапись'}.get(t, t)))
    return out


class ArchivePages:
    """Mixin: writes OUT/archive."""

    def jd(self):
        return base64.urlsafe_b64encode(json.dumps({'user_id': SELF_ID, 'time_current': EXPORT_TS - TZ},
                                                   separators=(',', ':')).encode()).decode().rstrip('=')

    def page(self, rel, tmpl, crumbs_html, body, head_extra=None):
        p = '../' * rel.count('/')
        top = PAGE_HEAD.format(jd=self._jd, p=p)
        if tmpl == 'A':
            html_ = top + PAGE_A.format(crumbs=crumbs_html, body=body)
        elif tmpl == 'B':
            html_ = top + PAGE_B.format(crumbs=crumbs_html, body=body)
        else:
            html_ = top + tmpl.format(body=body)
        if head_extra:
            html_ = html_.replace('      <h2 class="page_block_h2">\n' + HEADER_BLOCK.format(crumbs=crumbs_html), head_extra, 1)
        write_bytes(os.path.join(self.src, rel), html_.encode('cp1251'))

    def write_archive(self):
        self._jd = self.jd()
        log('Writing the fake archive')
        self.write_index()
        self.write_messages()
        self.write_profile()
        self.write_wall()
        self.write_albums()
        self.write_likes()
        self.write_my_comments()
        self.write_support()
        self.write_stubs()

    def write_index(self):
        blocks = []
        for title, items in INDEX_MENU:
            rows = ''.join('<div class="item">\n  <div class=\'item__main\'><div class="index-row">\n  <a class="menu__page-link" href="%s">\n'
                           '    <span class="archive__page-icon archive__page-icon--%s"></span>\n    <div>%s</div>\n  </a>\n'
                           '</div></div>\n  \n  \n</div>' % (h, icon, enc(label)) for h, icon, label in items)
            blocks.append('<div class="page_block">\n<h2 class="page_block_h2">\n' + HEADER_BLOCK.format(crumbs=enc(title)) +
                          '</h2>\n<div class="wrap_page_content">\n  ' + rows + '\n</div>\n</div>\n')
        made = EXPORT
        body = ('    <div class="page_content clear_fix">\n<div class="menu">\n<!--menu-->\n' + ''.join(blocks) +
                '<!--/menu-->\n</div>\n   </div>\n   <div class="footer">\n     <div class="generated">Архив был создан %d %s %d в %d:%02d:%02d за 412.37 секунд</div>\n'
                '   </div>\n  </div>\n</body>\n</html>' % (made.day, RU_MON[made.month - 1], made.year, made.hour, made.minute, made.second))
        write_bytes(os.path.join(self.src, 'index.html'), (PAGE_HEAD.format(jd=self._jd, p='') + body).encode('cp1251'))

    # -- messages --
    def header_who(self, uid):
        if uid == SELF_ID:
            return 'Вы, '
        return '<a href="https://vk.ru/%s%d">%s</a>, ' % ('id' if uid > 0 else 'club', abs(uid), enc(self.name(uid)))

    def msg_html(self, m):
        hdr = self.header_who(m['from_id']) + hdr_date(m['lts'])
        if m['edited']:
            hdr += "<span class='message-edited' title='%s'> (ред.)</span>" % hdr_date(m['edited'])
        if m['service']:
            kl = m['service']
        else:
            kl = stubs_of(m['atts'])
            n = len(m['fwd']) + (1 if m['reply'] else 0)
            if n:
                kl.append(att_stub(fwd_label(n)))
            kl = ''.join(kl)
        return ('<div class="item">\n  <div class=\'item__main\'><div class="message" data-id="%d">\n'
                '  <div class="message__header">%s</div>\n  <div>%s<div class="kludges">%s</div></div>\n</div></div>\n  \n  \n</div>') % (
            m['id'], hdr, enc(m['text']), kl)

    def write_messages(self):
        peers = sorted(self.msgs, key=lambda p: (p >= 2000000000, p > 0, p))
        rows = ''.join('<div class="item">\n  <div class=\'item__main\'><div class="message-peer">\n  <div class="message-peer--id">\n'
                       '    <a href="%d/messages0.html">%s</a>\n  </div>\n</div></div>\n  \n  \n</div>' % (p, enc(self.name(p)))
                       for p in peers if self.msgs[p])
        self.page('messages/index-messages.html', 'B', crumbs([('Профиль', '../index.html')], 'Сообщения'), rows)
        for p in peers:
            lst = sorted(self.msgs[p], key=lambda m: (m['lts'], m['id']), reverse=True)
            if not lst:
                continue
            chunks = [lst[i:i + 50] for i in range(0, len(lst), 50)]
            names = ['messages%d.html' % (i * 50) for i in range(len(chunks))]
            cr = crumbs([('Профиль', '../../index.html'), ('Сообщения', '../index-messages.html')], self.name(p))
            for i, ch in enumerate(chunks):
                body = ''.join(self.msg_html(m) for m in ch) + pagination(names, i)
                self.page('messages/%d/%s' % (p, names[i]), 'A', cr, body)

    # -- profile --
