        body = ''.join(item('<a href="https://vk.ru/id%d" class="mem_link">%s</a>' % (u, enc(self.name(u))),
                            list_date(lts_of(date(2016 + k * 3, 4 + k, 11 + k), 14 + k, 3 * k)))
                       for k, u in enumerate(self.blacklist))
        self.page('profile/blacklist.html', 'B', crumbs([('Профиль', '../index.html')], 'Чёрный список'), body)
