class Conv:
    def __init__(self, peer, scene, total, start, end, shape, kind, **kw):
        self.peer, self.scene, self.total, self.start, self.end = peer, scene, total, start, end
        self.shape, self.kind = shape, kind      # kind: personal old work uni hike family football flat bot news
        self.roles = kw.get('roles', {})         # scene letter -> user id (group chats)
        self.pool = kw.get('pool', [])           # members for A/B/C/D in group chats
        self.photo_kinds = kw.get('photos', ['landscape', 'food', 'city'])
        self.photo_rate = kw.get('photo_rate', 0.05)
        self.showcase = kw.get('showcase')
        self.voice = kw.get('voice', 'friend')
        self.filler = kw.get('filler', 0.35)


class World(Engine, Content, ArchivePages, DataFiles):
    def __init__(self, seed, out, jobs):
        self.seed = seed
        self.rng = random.Random(seed)
        self.out = out
        self.src = os.path.join(out, 'archive')
        self.dst = os.path.join(out, 'archive_enriched')
        self.njobs = jobs
        self.users, self.groups, self.chats = {}, {}, {}
        self.media = {}           # media_index.json
        self.jobs = []            # pictures to draw
        self.files = []           # (rel, kind, args) other media files
        self.msgs = {}            # peer -> [message]
        self.convs = []
        self.seq = {'photo': 457239000, 'video': 456239000, 'doc': 437000000, 'audio': 456240000, 'poll': 701000000}
        self.gifts_received = []  # (lts, from_id, gift_id, text)
        self.used_names = set()
        self.next_uid = SELF_ID + 1
        self.stickers = []
        self.docs = {}            # owner_id_id -> doc object (for profile/documents.html and docs.json)
        self.need_gifts = set()
        self.ffmpeg = shutil.which('ffmpeg')
        self.exact = False

    # -- people --
    def add_user(self, first, last, sex, uid=None, style=None):
        uid = uid or self.next_uid
        self.next_uid = max(self.next_uid, uid + 1)
        self.used_names.add((first, last))
        r = random.Random(stable_seed(self.seed, 'user', uid))
        if style is None:
            style = r.choices(['portrait', 'landscape', 'cat', 'flowers', 'abstract', 'city'], [46, 18, 9, 9, 12, 6])[0]
        self.users[uid] = {'id': uid, 'first': first, 'last': last, 'sex': sex, 'style': style}
        return uid

    def random_user(self, sex=None, rng=None):
        rng = rng or self.rng
        sex = sex or rng.choice('mf')
        taken = {surname(u['last'], False) if u['sex'] == 'm' else u['last'] for u in self.users.values()}
        for attempt in range(200):
            first = rng.choice(MALE if sex == 'm' else FEMALE)
            base = rng.choice(SURNAMES)
            last = surname(base, sex == 'f')
            if (first, last) in self.used_names or (attempt < 150 and (base in taken or surname(base, True) in taken)):
                continue
            return self.add_user(first, last, sex)
        raise RuntimeError('ran out of names')

    def name(self, i):
        if i >= 2000000000:
            return self.chats[i]['title']
        if i > 0:
            u = self.users[i]
            return '%s %s' % (u['first'], u['last'])
        return self.groups[-i]['name']

    def sex(self, i):
        return self.users[i]['sex'] if 0 < i < 2000000000 else 'm'

    def build_people(self):
        U = self.add_user
        U('Алексей', 'Смирнов', 'm', SELF_ID, style='landscape')
        self.KATYA = U('Екатерина', 'Белова', 'f', 100000001, style='portrait')
        self.DIMA = U('Дмитрий', 'Козлов', 'm', 100000002, style='portrait')
        self.MOM = U('Ирина', 'Смирнова', 'f', 100000003, style='flowers')
        self.DAD = U('Сергей', 'Смирнов', 'm', 100000004, style='landscape')
        self.OLYA = U('Ольга', 'Смирнова', 'f', 100000005, style='portrait')
        self.GRANDMA = U('Галина', 'Смирнова', 'f', 100000006, style='flowers')
