def render_all(world, jobs):
    uniq, seen = [], set()
    for j in world.jobs:
        if j[5] not in seen:
            seen.add(j[5])
            uniq.append(j)
    files = [f for f in world.files if f[1] != 'video']
    videos = [f for f in world.files if f[1] == 'video']
    log('Drawing %d pictures and %d other files with %d processes' % (len(uniq), len(files), jobs))
    t0 = time.time()
    tasks = [(world.dst, j) for j in uniq]
    ftasks = [(world.dst, f) for f in files]
    if jobs <= 1:
        for t in tasks:
            render_job(t)
        for t in ftasks:
            make_file(t)
    else:
        with ProcessPoolExecutor(jobs) as ex:
            list(ex.map(render_job, tasks, chunksize=4))
            list(ex.map(make_file, ftasks, chunksize=8))
    log('   done in %.0fs' % (time.time() - t0))
    if videos and world.ffmpeg:
        log('Making %d short video clips with ffmpeg' % len(videos))
        with ThreadPoolExecutor(max(2, min(8, jobs))) as ex:
            list(ex.map(make_video, [(world.ffmpeg, world.dst, rel, a[0]) for rel, _, a in videos]))
    have = set()
    for dp, dn, fn in os.walk(os.path.join(world.dst, 'media')):
        for f in fn:
            have.add(os.path.relpath(os.path.join(dp, f), world.dst).replace(os.sep, '/'))
    missing = [k for k, rel in world.media.items() if rel not in have]
    for k in missing:
        del world.media[k]
    if missing:
        log('   %d media files could not be made (left out of media_index.json)' % len(missing))


def prepare_out(out):
    os.makedirs(out, exist_ok=True)
    marker = os.path.join(out, MARKER)
    targets = [os.path.join(out, x) for x in ('archive', 'archive_enriched')]
    if any(os.path.exists(t) for t in targets) and not os.path.exists(marker):
        sys.exit('%s already has archive/ or archive_enriched/ that this script did not make; choose another folder.' % out)
    for t in targets:
        shutil.rmtree(t, ignore_errors=True)
    with open(marker, 'w') as f:
        f.write('made by make_demo_archive.py; archive/ and archive_enriched/ here are overwritten on every run\n')


def main():
    ap = argparse.ArgumentParser(description='Builds a fake (but realistic-looking) VK archive for the README screenshots.')
    ap.add_argument('out', help='output folder: archive/ and archive_enriched/ are created inside')
    ap.add_argument('--style', help="style.css from a real VK export (VK's file, not redistributed here)")
    ap.add_argument('--seed', type=int, default=2026, help='random seed (default 2026)')
    ap.add_argument('--jobs', type=int, default=0, help='drawing processes (default: number of CPUs)')
    ap.add_argument('--no-video', action='store_true', help='do not make video clips even if ffmpeg is available')
    a = ap.parse_args()
    if sys.version_info < (3, 9):
        sys.exit('Python 3.9+ is needed')
    out = os.path.abspath(a.out)
    jobs = a.jobs or min(16, os.cpu_count() or 2)
    t0 = time.time()
    prepare_out(out)
    w = World(a.seed, out, jobs)
    if a.no_video:
        w.ffmpeg = None
    log('Inventing people and %s' % ('conversations'))
    w.build_people()
    w.build_convs()
    w.build_stickers()
    w.gen_all()
    w.build_wall()
    w.build_albums()
    w.build_likes()
    w.build_my_comments()
    w.build_extras()
    w.build_support()
    n = sum(len(v) for v in w.msgs.values())
    log('%d conversations, %d messages' % (len(w.msgs), n))
    w.write_archive()
    if a.style:
        shutil.copyfile(a.style, os.path.join(w.src, 'style.css'))
    else:
        write_bytes(os.path.join(w.src, 'style.css'), FALLBACK_CSS.encode('utf-8'))
    w.schedule_avatars()
    render_all(w, jobs)
    w.write_data()
    log('Done in %.0fs. Now run:\n    python3 vk_archive_enrich.py "%s" "%s" --offline --github-activity' % (
        time.time() - t0, w.src, w.dst))


if __name__ == '__main__':
    main()
